const nivel = parseFloat(msg.payload);
if (nivel <= 20) {
    msg.payload = 'ON';
} else if (nivel >= 95) {
    msg.payload = 'OFF';
} else {
    return null;
}
return msg;

if (msg.payload === 'CORTE') {
    flow.set('red_ok', false);
    msg.payload = 'ON';
} else {
    flow.set('red_ok', true);
    msg.payload = 'OFF';
}
return msg;

const redOk = flow.get('red_ok') || false;
const v = parseFloat(msg.payload);
if (!redOk) return null;
const cargando = flow.get('cargando') || false;
if (v < 12.0) {
    flow.set('cargando', true);
    msg.payload = 'ON';
} else if (v >= 12.6 && cargando) {
    flow.set('cargando', false);
    msg.payload = 'OFF';
} else {
    return null;
}
return msg;
